insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Contran estabelecer as normas regulamentares do Código e as diretrizes da Política Nacional de Trânsito; coordenar os órgãos do Sistema; criar Câmaras Temáticas; fixar seu regimento e as diretrizes de funcionamento dos Cetran e do Contrandife e das JARI; zelar pela uniformidade das normas; normatizar o enquadramento das condutas, a fiscalização, as penalidades e a arrecadação das multas; responder a consultas; normatizar aprendizagem, habilitação, documentos de condutores, registro e licenciamento de veículos; aprovar a sinalização e os equipamentos de trânsito; avocar processos sobre conflitos de competência; dirimir conflitos de circunscrição; e normatizar o processo de formação do candidato à CNH, com conteúdo, carga horária, avaliações e exames. As propostas de normas regulamentares passam por consulta pública de, no mínimo, 30 dias. Em urgência, o presidente pode editar deliberação ad referendum do Plenário, que perde eficácia se não aprovada em 120 dias, mantidos os efeitos já produzidos.', '["Normas regulamentares e diretrizes da política de trânsito.","Câmaras Temáticas e regimentos dos Cetran e JARI.","Normatizar habilitação, registro, licenciamento e formação do candidato.","Consulta pública de, no mínimo, 30 dias.","Deliberação ad referendum perde eficácia em 120 dias se não aprovada."]'::jsonb, '["ATUALIZAÇÃO: o inciso XV (formação do candidato) e as regras de consulta pública e deliberação ad referendum vieram de leis posteriores.","Consulta pública de no mínimo 30 dias para normas regulamentares.","Deliberação ad referendum: perde eficácia em 120 dias, mantidos os efeitos."]'::jsonb, 'A resolução que padroniza a sinalização vem do Contran.', '["Assertiva que atribui ao Detran a edição das normas regulamentares do Código erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete aos Cetran e ao Contrandife cumprir e fazer cumprir a legislação de trânsito; elaborar normas no âmbito de suas competências; responder a consultas; estimular campanhas educativas; julgar os recursos interpostos contra decisões das JARI e dos órgãos executivos estaduais nos casos de inaptidão permanente constatada nos exames de aptidão física, mental ou psicológica; indicar representante para a comissão que examina candidatos com deficiência física; acompanhar e coordenar as atividades de trânsito no Estado, reportando-se ao Contran; dirimir conflitos de circunscrição entre Municípios; informar o Contran sobre o cumprimento do art. 333; e designar junta especial de saúde nos recursos deferidos. Das decisões do Cetran nos recursos do inciso V não cabe recurso na esfera administrativa.', '["Normas e consultas no âmbito estadual ou distrital.","Julga recursos contra decisões das JARI.","Julga recursos de inaptidão permanente nos exames de aptidão.","Dirime conflitos de circunscrição entre Municípios.","Sem recurso administrativo contra as decisões do inciso V."]'::jsonb, '["Cetran julga recursos contra decisões das JARI e nos casos de inaptidão permanente.","Das decisões do inciso V NÃO cabe recurso administrativo.","Suas normas valem no âmbito estadual ou distrital."]'::jsonb, 'O Cetran responde a consultas sobre a aplicação da legislação no estado.', '["Assertiva que atribui ao Cetran a edição de normas nacionais erra: suas normas valem no âmbito estadual."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao órgão máximo executivo de trânsito da União cumprir e fazer cumprir a legislação de trânsito e a execução das normas e diretrizes do Contran; supervisionar, coordenar e fiscalizar os órgãos delegados e a execução da Política Nacional de Trânsito; articular-se com os órgãos dos demais entes; entre outras atribuições relativas a registros, estatísticas e fiscalização.', '["Cumprir as normas do Contran.","Supervisão e correição dos órgãos delegados.","Articulação com os sistemas de trânsito, transporte e segurança pública.","Manter o Renach, o Renavam e a estatística nacional de trânsito.","Administrar o fundo nacional de segurança e educação de trânsito."]'::jsonb, '["Executa e supervisiona; não edita as normas regulamentares, que são do Contran.","Mantém o Renach (habilitações) e o Renavam (veículos)."]'::jsonb, 'O órgão federal supervisiona a execução da política nacional.', '["Assertiva que dá ao órgão máximo executivo da União a função normativa do Contran erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trânsito de veículos obedece a normas como a circulação pelo lado direito, admitidas exceções sinalizadas; a distância de segurança lateral e frontal; a preferência em local não sinalizado, que é de quem circula pela rodovia, de quem circula pela rotatória e, nos demais casos, de quem vem pela direita; as faixas da direita para veículos mais lentos e de maior porte e as da esquerda para ultrapassagem; o trânsito sobre passeios e acostamentos só para entrar ou sair de imóveis; a prioridade dos veículos precedidos de batedores; e a prioridade e livre circulação dos veículos de socorro, polícia, fiscalização e ambulâncias em serviço de urgência, com alarme sonoro e luz intermitente acionados, quando todos devem liberar a faixa da esquerda e os pedestres aguardar no passeio.', '["Circulação pela direita.","Distância de segurança.","Preferência em local não sinalizado: rodovia, rotatória, depois quem vem pela direita.","Faixas da direita para os mais lentos e da esquerda para a ultrapassagem.","Prioridade e livre circulação dos veículos de urgência em serviço."]'::jsonb, '["Sem sinalização: preferência de quem circula pela rodovia ou pela rotatória; nos demais casos, de quem vem pela direita.","Alarme e luz intermitente só podem ser usados na efetiva prestação de serviço de urgência.","Passeios e acostamentos só podem ser usados para entrar ou sair de imóveis ou áreas especiais."]'::jsonb, 'O condutor mantém distância de segurança do veículo à frente.', '["Assertiva que permite circular pela esquerda como regra erra: a regra é a direita."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-29'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitar em locais e horários não permitidos pela regulamentação estabelecida pela autoridade competente é infração média, com multa, para todos os tipos de veículos. O antigo inciso II, que tratava de veículos específicos como os de carga, foi revogado pela Lei nº 9.602, de 1998, e hoje todas as restrições de local e horário se enquadram no inciso I.', '["Infração média, para todos os tipos de veículos.","Inciso II revogado: todas as restrições se enquadram no inciso I."]'::jsonb, '["ATUALIZAÇÃO: o inciso II foi revogado pela Lei nº 9.602, de 1998; hoje só vale o inciso I.","Média, com quatro pontos, também para caminhões em restrição de circulação."]'::jsonb, 'O caminhão que circula em horário proibido pela placa é autuado no art. 187, I.', '["Assertiva que classifica como grave a circulação de caminhão em local ou horário proibido erra: o inciso II foi revogado e vale a infração média."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-187'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();
